import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [screen, setScreen] = useState("list");

  if (screen === "detail") {
    return (
      <View style={styles.screen}>
        <Text nativeID="detailTitle" style={styles.h}>Дэлгэрэнгүй</Text>
        <Pressable nativeID="back" style={styles.btn} onPress={() => setScreen("list")}>
          <Text style={styles.btnText}>← Буцах</Text>
        </Pressable>
      </View>
    );
  }

  return (
    <View style={styles.screen}>
      <Text style={styles.h}>Бараанууд</Text>
      <Pressable nativeID="open" style={styles.btn} onPress={() => setScreen("detail")}>
        <Text style={styles.btnText}>Дэлгэрэнгүй үзэх</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 16, justifyContent: "center" },
  h: { fontSize: 24, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#fff", fontSize: 16, fontWeight: "bold" },
});

registerRootComponent(App);
